import{_ as a,o as i,c as l,a2 as o}from"./chunks/framework.x7b91k6X.js";const p=JSON.parse('{"title":"第 16 话 · 开播即卡：七跳链路与弱网治理","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.16-audio-video-pipeline.md","filePath":"comics/EP.16-audio-video-pipeline.md","lastUpdated":1793856207000}'),t={name:"comics/EP.16-audio-video-pipeline.md"};function r(n,e,s,d,h,u){return i(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="第-16-话-·-开播即卡-七跳链路与弱网治理" tabindex="-1">第 16 话 · 开播即卡：七跳链路与弱网治理 <a class="header-anchor" href="#第-16-话-·-开播即卡-七跳链路与弱网治理" aria-label="Permalink to &quot;第 16 话 · 开播即卡：七跳链路与弱网治理&quot;">​</a></h1><blockquote><p>服务端全绿，用户却一直黑屏。问题不在「服务」，在「链路」。 本话漫画：<a href="./EP.16-audio-video-pipeline.svg">EP.16-audio-video-pipeline.svg</a></p></blockquote><h2 id="这一话的冲突" tabindex="-1">这一话的冲突 <a class="header-anchor" href="#这一话的冲突" aria-label="Permalink to &quot;这一话的冲突&quot;">​</a></h2><p>直播上线首日，机房大盘漂亮得像样板间：CPU 40%、带宽余量 60%、日志没有任何 error。 但客服群里刷屏：开播 5 秒还在转圈，弹幕从「卡了」升级成「主播跑路」。</p><p>Swifty 的第一反应也是查服务端——直到 Runtime 长老把问题掰成两半： <strong>用户感知的是端到端链路，而你监控的只是其中一跳。</strong> 这一话要建立一张七跳地图，并且让每一跳都打上同口径的埋点。</p><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>Swifty</strong>：负责客户端播放器的年轻工程师，习惯从服务端日志找答案。</li><li><strong>Runtime 长老</strong>：把「链路」拆成可观测节点的人，坚持先同口径、再优化。</li><li><strong>产品同学</strong>：只关心「开播几秒能看到画面」，对指标名不感兴趣。</li><li><strong>值班运维</strong>：手持全绿大盘，却解释不了黑屏。</li></ul><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格-1-·-痛点现场-开播-5-秒黑屏" tabindex="-1">格 1 · 痛点现场：开播 5 秒黑屏 <a class="header-anchor" href="#格-1-·-痛点现场-开播-5-秒黑屏" aria-label="Permalink to &quot;格 1 · 痛点现场：开播 5 秒黑屏&quot;">​</a></h3><ul><li>左侧手机预览窗一直转圈，右侧大盘三块全绿；</li><li>在线人数 1200 → 300，说明不是「没人看」，是「看不了」；</li><li>弹幕与客服双重报警，逼着团队承认：<strong>监控口径漏了客户端链路</strong>。</li></ul><h3 id="格-2-·-机制登场-弱网三件套先保连续" tabindex="-1">格 2 · 机制登场：弱网三件套先保连续 <a class="header-anchor" href="#格-2-·-机制登场-弱网三件套先保连续" aria-label="Permalink to &quot;格 2 · 机制登场：弱网三件套先保连续&quot;">​</a></h3><ul><li>码率阶梯（ABR）：4M → 2.5M → 1.8M → 1.2M，按缓冲水位与吞吐升降档；</li><li>FEC + NACK：关键帧冗余约 20%，普通帧 NACK 最多 2 次，重传超 200ms 直接放弃；</li><li>抖动缓冲：<code>depth = P95 抖动 × 2 + 30ms</code>，最低不低于 60ms；</li><li>升档要同时满足四个条件，降档分「无条件」与「安全」两档，避免来回抖动。</li></ul><h3 id="格-3-·-七跳链路-四个大节点-三个小节点" tabindex="-1">格 3 · 七跳链路：四个大节点 + 三个小节点 <a class="header-anchor" href="#格-3-·-七跳链路-四个大节点-三个小节点" aria-label="Permalink to &quot;格 3 · 七跳链路：四个大节点 + 三个小节点&quot;">​</a></h3><ul><li>大节点：采集 → 编码 → 传输 → 播放；</li><li>小节点：前处理 → 封装 → 分发；</li><li>每一跳都要能回答两件事：<strong>耗时多少、丢了什么</strong>；</li><li>传送门式统一命名：<code>capture / encode / send / play</code>，埋点字段同名同义；</li><li>协议选型：RTMP 上行 2~10s、SRT 200ms~2s 抗弱网、WebRTC 100~400ms 适合互动。</li></ul><h2 id="runtime-长老划重点" tabindex="-1">Runtime 长老划重点 <a class="header-anchor" href="#runtime-长老划重点" aria-label="Permalink to &quot;Runtime 长老划重点&quot;">​</a></h2><blockquote><p>先把七跳各打一个同口径的 signpost，再谈优化；否则「卡」永远只能靠猜。</p></blockquote><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问：服务端 99.9% 可用、播放成功率 98%，为什么用户仍可能大面积黑屏？</strong></p><p>答：可用性只描述「服务活着」，不代表「画面到了」。首帧耗时、分发 TTFB、弱网重连、 抖动缓冲水位都发生在服务端之外；缺了客户端七跳埋点，就无法把「黑屏」定位到具体一跳。</p><h2 id="去实验室" tabindex="-1">去实验室 <a class="header-anchor" href="#去实验室" aria-label="Permalink to &quot;去实验室&quot;">​</a></h2><ul><li>深读：<a href="./../16-audio-video-pipeline">第 16 章 · 音视频与实时链路</a></li><li>动手：<code>examples/MediaPipeline</code> —— 码率阶梯、抖动缓冲、重连与音频会话的纯逻辑实现；</li><li>观察：把丢包率从 0% 调到 8%，看缓冲水位与降档时机如何变化。</li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>三盏绿灯、一次回滚——当分母和样本都对不上时，指标越漂亮越危险。</p><hr><p><sub>银翼工坊 Silverwing Workshop · EP.16 · 本话漫画 <a href="./EP.16-audio-video-pipeline.svg">EP.16-audio-video-pipeline.svg</a></sub></p>',25)])])}const m=a(t,[["render",r]]);export{p as __pageData,m as default};
